/**
 * The old password stops working at once. Give a username to rename the login and a password to choose it; empty fields keep the username and generate a password.
 * @summary New Xtream credentials for an IPTV app device, shown once
 */
export const meDevicesXtreamCredentials = async (
  id: string,
  myCredentialResetRequest?: MyCredentialResetRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<MyIssuedCredential> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<MyIssuedCredential>(getMeDevicesXtreamCredentialsUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(myCredentialResetRequest),
  });
};

