export const getWatchHistoryDeleteUrl = (id: string) => {
  return `/api/v1/watch-history/${encodeURIComponent(String(id))}`;
};

/**
 * A customer endpoint answering in the request's language.
 * @summary Forget one title (it also leaves continue-watching)
 */
export const watchHistoryDelete = async (
  id: string,
  options?: Parameters<typeof apiFetch>[1],
): Promise<void> => {
  return apiFetch<void>(getWatchHistoryDeleteUrl(id), {
    ...options,
    method: "DELETE",
  });
};

export const getWatchHistoryDeleteMutationKey = () => ["watchHistoryDelete"] as const;

export const getWatchHistoryDeleteMutationOptions = <
  TError = ErrorType<Problem>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof watchHistoryDelete>>,
    TError,
    WatchHistoryDeleteMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof apiFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof watchHistoryDelete>>,
  TError,
  WatchHistoryDeleteMutationVariables,
  TContext
> => {
  const mutationKey = getWatchHistoryDeleteMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof watchHistoryDelete>>,
    WatchHistoryDeleteMutationVariables
  > = (props) => {
    const { id } = props ?? {};

    return watchHistoryDelete(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

